// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {BANK_SAFE, LogFile} from "../src/BANK_SAFE.sol";

contract InvMutTest is Test {
    BANK_SAFE c;

    function setUp() public {
        c = new BANK_SAFE();
    }

    function testFuzz_property(address actor, uint256 depositAmount, uint256 collectAmount) public {
        vm.assume(actor != address(0));
        vm.assume(depositAmount > 0);
        vm.assume(depositAmount < type(uint128).max);

        LogFile log = new LogFile();
        c.SetLogFile(address(log));
        c.Initialized();

        vm.deal(actor, depositAmount);
        vm.prank(actor);
        c.Deposit{value: depositAmount}();

        uint256 balanceBefore = c.balances(actor);

        vm.prank(actor);
        try c.Collect(collectAmount) {} catch {}

        uint256 balanceAfter = c.balances(actor);
        assertTrue(balanceAfter <= balanceBefore);
    }
}

